insert into public.ai_styles (owner, name, prompt, category, shared)
select p.id, n.name, n.prompt, n.category, true
  from neu n cross join (select id from public.profiles where is_admin order by created_at limit 1) p
 where not exists (select 1 from public.ai_styles s where s.owner = p.id and s.name = n.name);
